"""The Med School Learning Foundation curriculum: 74 courses from kindergarten to medical school.
Writes work/courses_raw.json (writer-facing) and work/meta.json (site-facing extras)."""
import json, copy

TOE_RAW = {c['code']: c for c in json.load(open('/home/claude/toe/work/courses_raw.json'))}

STAGES = [
    ('K', 'Elementary school (K–5)', 'Numbers, reading and writing, science and the world around us, learned with a grown-up close by.'),
    ('J', 'Middle school (6–8)', 'Ratios to algebra, reading for evidence and argument, and the life, physical and earth sciences.'),
    ('H', 'High school (9–12)', 'Algebra through calculus, statistics, biology, chemistry, physics, English and history.'),
    ('C', 'College pre-medical', 'The biology, chemistry, physics, biochemistry, genetics and behavioral science medical schools expect, and the MCAT.'),
    ('M', 'Medical school foundations', 'Anatomy, embryology, histology, physiology, biochemistry, genetics, immunology, microbiology, pathology, pharmacology, evidence, ethics and clinical skills.'),
    ('S', 'Organ systems', 'Each body system from normal structure and function to disease, diagnosis and treatment.'),
    ('R', 'Clinical clerkships and boards', 'The core rotations, then integrated review for USMLE Step 1 and Step 2 CK.'),
]
LEVEL = {'K': 'elementary', 'J': 'middle', 'H': 'high', 'C': 'college', 'M': 'medical', 'S': 'medical', 'R': 'clinical'}
FINAL_MIN = {'elementary': 30, 'middle': 45, 'high': 60, 'college': 120, 'medical': 150, 'clinical': 180}
HOURS = {'elementary': '2–3', 'middle': '3–4', 'high': '4–6', 'college': '8–12', 'medical': '12–15', 'clinical': '12–15'}

COURSES = []

def C(code, title, profile, req, soft, purpose, why, ready, reading, units, project, supplement=None):
    assert len(units) == 6, code
    lvl = LEVEL[code[0]]
    fm = FINAL_MIN[lvl]
    u = []
    for i, (a, b, d) in enumerate(units):
        u.append({'weeks': [2 * i + 1, 2 * i + 2], 'topics': [a, b], 'deliverable': d})
    if lvl == 'elementary':
        u.append({'weeks': [13, 14], 'topics': ['Project and review', 'Final check'],
                  'deliverable': f'Finish the project with your grown-up; take the {fm}-minute final check in week 14.'})
        completion = 'finish the project with a grown-up, take the week 7 check-up and the week 14 final check, then redo any missed questions a week later. Show or tell one big idea from the course in your own words.'
    else:
        u.append({'weeks': [13, 14], 'topics': ['Project and review', 'Cumulative final'],
                  'deliverable': f'Submit the project; take an unseen {fm} minute final in week 14.'})
        completion = 'finish the project, take the week 7 midterm and week 14 cumulative final, then complete a new cumulative assessment after 1 to 2 weeks. Explain one major idea aloud without notes.'
    COURSES.append({'code': code, 'title': title, 'stage': code[0], 'level': lvl, 'profile': profile, 'req': req, 'soft': soft,
                    'prerequisites': (', '.join(req) if req else 'None') + ('; helpful: ' + ', '.join(soft) if soft else '') + '.',
                    'purpose': purpose, 'why': why, 'ready': ready,
                    'reading': {'title': reading[0], 'url': reading[1]}, 'readingScope': None, 'readingNote': None,
                    'units': u, 'project': project, 'completion': completion, 'supplement': supplement})

def REUSE(code, toe, title, req, soft, why, ready):
    t = copy.deepcopy(TOE_RAW[toe])
    lvl = LEVEL[code[0]]
    t.update({'code': code, 'title': title, 'stage': code[0], 'level': lvl, 'req': req, 'soft': soft,
              'prerequisites': (', '.join(req) if req else 'None') + '.', 'why': why, 'ready': ready,
              'supplement': None, 'reusedFrom': toe})
    t['purpose'] = t['purpose'].replace('Elective: ', '')
    t.pop('page', None)
    COURSES.append(t)

