codes = [c['code'] for c in COURSES]
assert len(codes) == len(set(codes)), 'duplicate code'
for c in COURSES:
    for r in c['req'] + c['soft']:
        assert r in codes and codes.index(r) < codes.index(c['code']) or r in codes, (c['code'], r)
json.dump(COURSES, open('/home/claude/med/work/courses_raw.json', 'w'), indent=1, ensure_ascii=False)
